"""What this target did with every node of the published tree it read.

A node gets one representation per fact, and a widening carries its declaration as a
required argument, so an undeclared widening cannot be written here (target rules § 7).
The validation layer re-checks every fact the data model does not carry exactly, which is
what makes a widened type sound rather than merely declared (§ 5).
"""

from __future__ import annotations

from collections.abc import Sequence

from ._runtime import Exact, Refused, Representation, Widened

__all__ = ["NODES", "Node", "of", "widenings"]


class Node(tuple[str, str, str, str, Representation]):
    """One node, the symbol written for it, the layer that carries the fact, and the fact's representation."""

    __slots__ = ()

    @property
    def node(self) -> str:
        """The published node, as a document's `$id` and a pointer."""
        return self[0]

    @property
    def symbol(self) -> str:
        """The name this package writes for it."""
        return self[1]

    @property
    def layer(self) -> str:
        """Which layer carries the fact: `data-model`, `validation`, or `helpers`."""
        return self[2]

    @property
    def fact(self) -> str:
        """The fact, in the schema's own vocabulary."""
        return self[3]

    @property
    def representation(self) -> Representation:
        """`Exact`, `Widened` with its declaration, or `Refused` with its reason."""
        return self[4]


