def of(node: str) -> Sequence[Node]:
    """Every representation this target gave the facts of `node`."""
    return tuple(entry for entry in NODES if entry.node == node)


def widenings() -> Sequence[Node]:
    """Every fact the data model does not carry exactly, which the validation layer carries instead."""
    return tuple(entry for entry in NODES if isinstance(entry.representation, Widened))
